// @generated by `cargo xtask grammars generate`.

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let opt_level = grammar_c_opt_level();

    let mut c_compiler = cc::Build::new();
    c_compiler
        .std("c11")
        .opt_level(opt_level)
        .flag_if_supported("-Wno-unused-parameter")
        .flag_if_supported("-Wno-unused-but-set-variable")
        .flag_if_supported("-Wno-unused-value")
        .flag_if_supported("-Wno-implicit-fallthrough")
        .flag_if_supported("-Wno-sign-compare")
        .flag_if_supported("-Wno-trigraphs");
    // The vendored scanners trip `-Wall -Wextra`, which cc-rs enables by
    // default, and none of it is actionable here. `-Wno-macro-redefined` is
    // Clang-only: GCC mentions unknown `-Wno-*` options only while diagnosing
    // something else, which fools `flag_if_supported` into adding a bogus
    // "unrecognized command-line option" note to every other C warning.
    if c_compiler.try_get_compiler()?.is_like_clang() {
        c_compiler.flag("-Wno-macro-redefined");
    }
    if opt_level == 0 {
        // GCC 15+ stops emitting jump tables at `-O0`, and the generated lexer
        // is one giant switch, so keep them even in unoptimized builds.
        c_compiler.flag_if_supported("-fjump-tables");
    }
    #[cfg(target_env = "msvc")]
    c_compiler.flag("-utf-8");

    c_compiler.include("src");

    let target = std::env::var("TARGET")?;
    if target.starts_with("wasm32-unknown") {
        let wasm_headers = std::env::var("DEP_TREE_SITTER_LANGUAGE_WASM_HEADERS")?;
        c_compiler.include(wasm_headers);
    }

    c_compiler.file("src/parser.c");
    println!("cargo:rerun-if-changed=src/parser.c");
    c_compiler.compile("tree-sitter-json");

    Ok(())
}

/// Optimization level for the generated C parser.
///
/// `parser.c` is made up almost entirely of generated tables and one huge lexer
/// function, so optimizing it is expensive for the C compiler (seconds per
/// grammar instead of fractions of a second) while every parse pays for the
/// result. Unoptimized debug builds keep `cargo build` fast, and release builds
/// use `-O2`: `-O3` on these tables mostly buys compile time.
///
/// Set `ZZZ_GRAMMAR_C_OPT_LEVEL` (0-3) to override, e.g. to A/B `-O2` against
/// `-O3` without touching the workspace.
fn grammar_c_opt_level() -> u32 {
    println!("cargo:rerun-if-env-changed=ZZZ_GRAMMAR_C_OPT_LEVEL");

    if let Some(level) = std::env::var("ZZZ_GRAMMAR_C_OPT_LEVEL")
        .ok()
        .and_then(|level| level.trim().parse::<u32>().ok())
    {
        return level;
    }

    match std::env::var("OPT_LEVEL").as_deref() {
        Ok("0") => 0,
        Ok("1") => 1,
        // 2, 3, `s` and `z` all land on `-O2`.
        _ => 2,
    }
}
